136	pub enum WaylandSurfaceState {
137	    Xdg(WaylandXdgSurfaceState),
138	    LayerShell(WaylandLayerSurfaceState),
139	    Popup(WaylandPopupSurfaceState),
140	}
141	
142	impl WaylandSurfaceState {
143	    fn new(
144	        surface: &wl_surface::WlSurface,
145	        globals: &Globals,
146	        params: &WindowParams,
147	        parent: Option<WaylandWindowStatePtr>,
148	        popup_grab: Option<(u32, wl_seat::WlSeat)>,
149	        target_output: Option<wl_output::WlOutput>,
150	    ) -> anyhow::Result<Self> {
151	        // For layer_shell windows, create a layer surface instead of an xdg surface
152	        if let WindowKind::LayerShell(options) = &params.kind {
153	            let Some(layer_shell) = globals.layer_shell.as_ref() else {
154	                return Err(LayerShellNotSupportedError.into());
155	            };
156	
157	            let layer_surface = layer_shell.get_layer_surface(
158	                &surface,
159	                target_output.as_ref(),
160	                super::layer_shell::wayland_layer(options.layer),
161	                options.namespace.clone(),
162	                &globals.qh,
163	                surface.id(),
164	            );
165	
166	            let width = f32::from(params.bounds.size.width);
167	            let height = f32::from(params.bounds.size.height);
168	            layer_surface.set_size(width as u32, height as u32);
169	
170	            layer_surface.set_anchor(super::layer_shell::wayland_anchor(options.anchor));
171	            layer_surface.set_keyboard_interactivity(
172	                super::layer_shell::wayland_keyboard_interactivity(options.keyboard_interactivity),
173	            );
174	
175	            if let Some(margin) = options.margin {
176	                layer_surface.set_margin(
177	                    f32::from(margin.0) as i32,
178	                    f32::from(margin.1) as i32,
179	                    f32::from(margin.2) as i32,
180	                    f32::from(margin.3) as i32,
181	                )
182	            }
183	
184	            if let Some(exclusive_zone) = options.exclusive_zone {
185	                layer_surface.set_exclusive_zone(f32::from(exclusive_zone) as i32);
186	            }
187	
188	            if let Some(exclusive_edge) = options.exclusive_edge {
189	                Self::apply_exclusive_edge(&layer_surface, options.anchor, exclusive_edge);
190	            }
191	
192	            return Ok(WaylandSurfaceState::LayerShell(WaylandLayerSurfaceState {
193	                layer_surface,
194	                anchor: options.anchor,
195	            }));
196	        }
197	
198	        if let WindowKind::AnchoredPopup(options) = &params.kind {
199	            let Some(parent) = parent.as_ref() else {
200	                return Err(anyhow::anyhow!("popup parent window not found"));
201	            };
202	
203	            let positioner = build_popup_positioner(
204	                globals,
205	                options,
206	                params.bounds.size,
207	                parent.window_geometry(),
208	            );
209	
210	            let xdg_surface = globals
211	                .wm_base
212	                .get_xdg_surface(&surface, &globals.qh, surface.id());
213	
214	            // A layer-shell parent takes a null xdg parent and is attached via the layer
215	            // surface. Every other surface kind has an xdg_surface to parent to directly.
216	            let xdg_popup = if let Some(parent_layer_surface) = parent.layer_surface() {
217	                let xdg_popup = xdg_surface.get_popup(None, &positioner, &globals.qh, surface.id());
218	                parent_layer_surface.get_popup(&xdg_popup);
219	                xdg_popup
220	            } else {
221	                xdg_surface.get_popup(
222	                    parent.xdg_surface().as_ref(),
223	                    &positioner,
224	                    &globals.qh,
225	                    surface.id(),
226	                )
227	            };
228	            positioner.destroy();
229	
230	            if let Some((serial, seat)) = popup_grab {
231	                xdg_popup.grab(&seat, serial);
232	            }
233	
234	            // Non-blocking: the parent keeps its input so it can dismiss the popup on
235	            // clicks in its own window.
236	            parent.add_child(surface.id(), false);
237	
238	            return Ok(WaylandSurfaceState::Popup(WaylandPopupSurfaceState {
239	                xdg_surface,
240	                xdg_popup,
241	                options: options.clone(),
242	                next_reposition_token: Cell::new(0),
243	            }));
244	        }
245	
246	        // All other WindowKinds result in a regular xdg surface
247	        let xdg_surface = globals
248	            .wm_base
249	            .get_xdg_surface(&surface, &globals.qh, surface.id());
250	
251	        let toplevel = xdg_surface.get_toplevel(&globals.qh, surface.id());
252	        let xdg_parent = parent.as_ref().and_then(|w| w.toplevel());
253	
254	        if params.kind == WindowKind::Floating || params.kind == WindowKind::Dialog {
255	            toplevel.set_parent(xdg_parent.as_ref());
256	        }
257	
258	        let dialog = if params.kind == WindowKind::Dialog {
259	            let dialog = globals.dialog.as_ref().map(|dialog| {
260	                let xdg_dialog = dialog.get_xdg_dialog(&toplevel, &globals.qh, ());
261	                xdg_dialog.set_modal();
262	                xdg_dialog
263	            });
264	
265	            if let Some(parent) = parent.as_ref() {
266	                parent.add_child(surface.id(), true);
267	            }
268	
269	            dialog
270	        } else {
271	            None
272	        };
273	
274	        if let Some(size) = params.window_min_size {
275	            toplevel.set_min_size(f32::from(size.width) as i32, f32::from(size.height) as i32);
276	        }
277	
278	        // Attempt to set up window decorations based on the requested configuration
279	        let decoration = globals
280	            .decoration_manager
281	            .as_ref()
282	            .map(|decoration_manager| {
283	                decoration_manager.get_toplevel_decoration(&toplevel, &globals.qh, surface.id())
284	            });
285	
286	        Ok(WaylandSurfaceState::Xdg(WaylandXdgSurfaceState {
287	            xdg_surface,
288	            toplevel,
289	            decoration,
290	            dialog,
291	        }))
292	    }
293	}
