307	pub struct WaylandPopupSurfaceState {
308	    xdg_surface: xdg_surface::XdgSurface,
309	    xdg_popup: xdg_popup::XdgPopup,
310	    // Kept so the popup can be re-anchored via `xdg_popup.reposition` when resized.
311	    options: PopupOptions,
312	    next_reposition_token: Cell<u32>,
313	}
314	
315	fn build_popup_positioner(
316	    globals: &Globals,
317	    options: &PopupOptions,
318	    size: Size<Pixels>,
319	    parent_geometry: Bounds<Pixels>,
