537	pub struct WaylandWindowStatePtr {
538	    state: Rc<RefCell<WaylandWindowState>>,
539	    callbacks: Rc<RefCell<Callbacks>>,
540	    frame_loop: Rc<Cell<FrameLoop>>,
541	    frame_ping: Ping,
542	}
543	
544	impl WaylandWindowState {
545	    pub(crate) fn new(
546	        handle: AnyWindowHandle,
547	        surface: wl_surface::WlSurface,
548	        surface_state: WaylandSurfaceState,
549	        appearance: WindowAppearance,
550	        viewport: Option<wp_viewport::WpViewport>,
551	        client: WaylandClientStatePtr,
552	        globals: Globals,
553	        gpu_context: gpui_wgpu::GpuContext,
554	        compositor_gpu: Option<CompositorGpuHint>,
555	        options: WindowParams,
556	        parent: Option<WaylandWindowStatePtr>,
557	    ) -> anyhow::Result<Self> {
558	        let renderer = {
559	            let raw_window = RawWindow {
560	                window: surface.id().as_ptr().cast::<c_void>(),
561	                display: surface
562	                    .backend()
563	                    .upgrade()
564	                    .unwrap()
565	                    .display_ptr()
566	                    .cast::<c_void>(),
567	            };
568	            let config = WgpuSurfaceConfig {
569	                size: Size {
570	                    width: DevicePixels(f32::from(options.bounds.size.width) as i32),
571	                    height: DevicePixels(f32::from(options.bounds.size.height) as i32),
572	                },
573	                transparent: true,
574	                // Prefer Mailbox to avoid blocking. Falls back to FIFO if Mailbox is unsupported.
575	                preferred_present_mode: Some(wgpu::PresentMode::Mailbox),
576	            };
577	            WgpuRenderer::new(gpu_context, &raw_window, config, compositor_gpu)?
578	        };
579	
580	        if let WaylandSurfaceState::Xdg(ref xdg_state) = surface_state {
581	            if let Some(title) = options.titlebar.and_then(|titlebar| titlebar.title) {
582	                xdg_state.toplevel.set_title(title.to_string());
583	            }
584	
585	            if let Some(app_id) = options.app_id.as_ref() {
586	                xdg_state.toplevel.set_app_id(app_id.clone());
587	            }
588	
589	            // Set max window size based on the GPU's maximum texture dimension.
590	            // This prevents the window from being resized larger than what the GPU can render.
591	            let max_texture_size = renderer.max_texture_size() as i32;
592	            xdg_state
593	                .toplevel
594	                .set_max_size(max_texture_size, max_texture_size);
595	        }
596	
597	        Ok(Self {
598	            surface_state,
599	            parent,
600	            children: FxHashMap::default(),
601	            surface,
602	            app_id: options.app_id,
603	            blur: None,
604	            viewport,
605	            globals,
606	            outputs: HashMap::default(),
607	            display: None,
608	            renderer,
609	            bounds: options.bounds,
610	            scale: 1.0,
611	            input_handler: None,
612	            decorations: WindowDecorations::Client,
613	            background_appearance: WindowBackgroundAppearance::Opaque,
614	            fullscreen: false,
615	            maximized: false,
616	            tiling: Tiling::default(),
617	            window_bounds: options.bounds,
618	            in_progress_configure: None,
619	            resize_throttle: false,
620	            client,
621	            appearance,
622	            handle,
623	            active: false,
624	            hovered: false,
625	            redraw_requested: false,
626	            presentation: PresentationState::Unpresented,
627	            pending_frame_callback: None,
628	            in_progress_window_controls: None,
629	            window_controls: WindowControls::default(),
630	            client_inset: None,
631	            accesskit_adapter: None,
632	        })
633	    }
634	
635	    pub fn is_transparent(&self) -> bool {
636	        self.decorations == WindowDecorations::Client
637	            || self.background_appearance != WindowBackgroundAppearance::Opaque
638	    }
639	
640	    fn update_subpixel_layout(&mut self) {
641	        use wayland_client::protocol::wl_output::Subpixel;
642	        let is_bgr = self
643	            .display
644	            .as_ref()
645	            .and_then(|(_, output)| output.subpixel)
646	            .is_some_and(|s| s == Subpixel::HorizontalBgr);
647	        self.renderer.set_subpixel_layout(is_bgr);
648	    }
649	
650	    pub fn primary_output_scale(&mut self) -> i32 {
651	        let mut scale = 1;
652	        let mut current_output = self.display.take();
653	        for (id, output) in self.outputs.iter() {
654	            if let Some((_, output_data)) = &current_output {
655	                if output.scale > output_data.scale {
656	                    current_output = Some((id.clone(), output.clone()));
657	                }
658	            } else {
659	                current_output = Some((id.clone(), output.clone()));
660	            }
661	            scale = scale.max(output.scale);
662	        }
663	        self.display = current_output;
664	        scale
665	    }
666	
667	    pub fn inset(&self) -> Pixels {
668	        match self.decorations {
669	            WindowDecorations::Server => px(0.0),
670	            WindowDecorations::Client => self.client_inset.unwrap_or(px(0.0)),
671	        }
672	    }
673	}
